func seedCustomerIdentity(ctx context.Context, tx *sql.Tx, siteID uuid.UUID, direction map[string]interface{}, logger *zap.Logger) error {
  email,name,reference := TrimSpace(direction["customer_email"/"customer_name"/"order_reference"])
  if email=="" && name=="" { return nil }
  UPDATE sites SET email=COALESCE(NULLIF(email,''),NULLIF($2,'')), company_name=COALESCE(NULLIF(company_name,''),NULLIF($3,'')), updated_at=now() WHERE id=$1;
  facts := [{id:business_name,kind:entity,claim,source{attested_by:'customer at order intake, reference '+ref},verified_at,writer_line}, {id:contact,kind:entity,claim:'Enquiries reach <email>.',...}]
  INSERT INTO site_specs (site_id,aspect,data,source,created_by,is_current,notes)
  SELECT $1,'evidence_base',$2::jsonb,'order_intake','seed_build_queue',true,$3
  WHERE NOT EXISTS (SELECT 1 FROM site_specs WHERE site_id=$1 AND aspect='evidence_base' AND is_current);
  RowsAffected==0 -> Info 'evidence_base already present, left untouched'; return nil }

if err := seedCustomerIdentity(ctx, tx, site.ID, entry.direction, logger); err != nil {
  tx.Rollback(); logger.Warn("SeedBuildQueueAction: customer identity seed failed", ...); skipped++; continue
}
